import{_ as e,o as l,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const q=JSON.parse('{"title":"渲染数据在计算中时最佳实践","description":"最佳实践 以下是基于 Exness 场景（大订单量、Vue 3、表格渲染）的 Web Worker 数据展示最佳实践： 3.1 管理加载状态 实践 ： 扩展 loading 状态，覆盖 useFetch 和 Worker 处理。 添加 workerLoading 状态，跟踪 Wo。","frontmatter":{"title":"渲染数据在计算中时最佳实践","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","进阶语言能力"],"description":"最佳实践 以下是基于 Exness 场景（大订单量、Vue 3、表格渲染）的 Web Worker 数据展示最佳实践： 3.1 管理加载状态 实践 ： 扩展 loading 状态，覆盖 useFetch 和 Worker 处理。 添加 workerLoading 状态，跟踪 Wo。","sidebarWeight":47,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/webworkers/渲染数据在计算中时最佳实践.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/07-进阶语言能力/渲染数据在计算中时最佳实践.md","filePath":"posts/JavaScript系统教程/07-进阶语言能力/渲染数据在计算中时最佳实践.md"}'),r={name:"posts/JavaScript系统教程/07-进阶语言能力/渲染数据在计算中时最佳实践.md"};function s(i,t,n,u,g,d){return l(),o("div",null,[...t[0]||(t[0]=[a('<div><h1 id="渲染数据在计算中时最佳实践" tabindex="-1">渲染数据在计算中时最佳实践 <a class="header-anchor" href="#渲染数据在计算中时最佳实践" aria-label="Permalink to &quot;渲染数据在计算中时最佳实践&quot;">​</a></h1><blockquote><p>本节目标：理解“渲染数据在计算中时最佳实践”的核心思路，并能把它用于实际开发或面试表达。 <strong>最佳实践</strong> 以下是基于 Exness 场景（大订单量、Vue 3、表格渲染）的 Web Worker 数据展示最佳实践： <strong>3.1 管理加载状态</strong></p></blockquote><ul><li><strong>实践</strong>： <ul><li>扩展 loading 状态，覆盖 useFetch 和 Worker 处理。</li><li>添加 workerLoading 状态，跟踪 Worker 的异步处理。</li></ul></li><li><strong>代码</strong>： const workerLoading = ref(false);watch(_data, (newData) =&gt; { if (!newData) return; workerLoading.value = true; <em>// 开始 Worker 处理</em> const rawMap = isMap(newData as OrderResp) ? toRaw((newData as OrderMapResp).data) : { <em>all: toRaw((newData as OrderListResp).data) }; worker.postMessage({ type: &#39;processOrders&#39;, data: { rawMap, isFoldMode: isFoldMode.value } });});worker.onmessage = (event: MessageEvent) =&gt; { const { type, data } = event.data as WorkerMessage; if (type === &#39;processedOrders&#39;) { unfoldRowMap.value = data.unfoldRowMap; foldRowMap.value = data.foldRowMap; unfoldList.value = data.unfoldList; foldList.value = data.foldList; stats.value = data.stats; totalFloatingPL.value = data.totalFloatingPL; totalCommission.value = data.totalCommission; workerLoading.value = false; <em>// Worker 处理完成</em> } else if (type === &#39;error&#39;) { console.error(&#39;Worker 错误:&#39;, data.message); workerLoading.value = false; }};</em>// 综合加载状态_const isLoading = computed(() =&gt; loading.value || workerLoading.value);</li></ul><p><strong>3.2 使用 Skeleton 组件</strong></p><ul><li><strong>实践</strong>： <ul><li>在初次加载或账户切换时，显示 Skeleton 表格。</li><li>使用 v-if 切换 Skeleton 和真实数据。</li></ul></li><li><strong>代码</strong>（OpenOrder.vue 示例）： &lt;template&gt; &lt;div&gt; &lt;template v-if=&quot;isLoading &amp;&amp; !data.length&quot;&gt; <em>&lt;!-- Skeleton --&gt;</em> &lt;el-table :data=&quot;Array(10).fill({})&quot; style=&quot;width: 100%&quot;&gt; &lt;el-table-column prop=&quot;SYMBOL&quot; label=&quot;Symbol&quot;&gt; &lt;template #default&gt; &lt;el-skeleton-item variant=&quot;text&quot; style=&quot;width: 80px&quot; /&gt; &lt;/template&gt; &lt;/el-table-column&gt; &lt;el-table-column prop=&quot;PROFIT&quot; label=&quot;Profit&quot;&gt; &lt;template #default&gt; &lt;el-skeleton-item variant=&quot;text&quot; style=&quot;width: 60px&quot; /&gt; &lt;/template&gt; &lt;/el-table-column&gt; <em>&lt;!-- 其他列 --&gt;</em> &lt;/el-table&gt; &lt;/template&gt; &lt;el-table v-else :data=&quot;data&quot; style=&quot;width: 100%&quot;&gt; &lt;el-table-column prop=&quot;SYMBOL&quot; label=&quot;Symbol&quot; /&gt; &lt;el-table-column prop=&quot;OPEN_PRICE&quot; label=&quot;Open Price&quot; /&gt; &lt;el-table-column prop=&quot;CURRENT_PRICE&quot; label=&quot;Current Price&quot; /&gt; &lt;el-table-column prop=&quot;PROFIT&quot; label=&quot;Profit&quot; /&gt; &lt;el-table-column prop=&quot;VOLUME&quot; label=&quot;Volume&quot; /&gt; &lt;/el-table&gt; &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import { useOpenOrder } from &#39;./useOpenOrder&#39;;import { ref } from &#39;vue&#39;;const accountInfo = ref({ name: &#39;exness&#39;, loginid: &#39;123&#39; });const { data, isLoading } = useOpenOrder(accountInfo);&lt;/script&gt;</li><li><strong>说明</strong>： <ul><li>使用 Element Plus 的 &lt;el-skeleton-item&gt; 或自定义 Skeleton。</li><li>条件：isLoading &amp;&amp; !data.length 确保初次加载显示 Skeleton，后续更新显示旧数据。</li></ul></li></ul><p><strong>3.3 保留旧数据</strong></p><ul><li><strong>实践</strong>： <ul><li>在 Worker 处理期间，保留 foldList 或 unfoldList 的旧值。</li><li>实时更新价格（newQuotePayload）保持表格活跃。</li></ul></li><li><strong>代码</strong>（已有逻辑支持）： <ul><li>当前代码已使用 shallowRef 和 ref 管理 foldList/unfoldList，默认保留旧值。</li><li>watch(tradeStore.newQuotePayload, ...) 实时更新 CURRENT_PRICE 和 PL，无需修改。</li></ul></li><li><strong>优化</strong>： <ul><li>确保 workerLoading 不清空 foldList/unfoldList： worker.onmessage = (event: MessageEvent) =&gt; { if (type === &#39;processedOrders&#39;) { <em>// 仅更新非空数据</em> if (data.unfoldList?.length) unfoldList.value = data.unfoldList; if (data.foldList?.length) foldList.value = data.foldList; workerLoading.value = false; }};</li></ul></li></ul><p><strong>3.4 优化表格渲染</strong></p><ul><li><strong>实践</strong>： <ul><li>使用虚拟滚动（如 el-table-v2）处理大订单量。</li><li>分页或懒加载减少 DOM 节点。</li></ul></li><li><strong>代码</strong>： &lt;el-table-v2 :columns=&quot;[ { key: &#39;SYMBOL&#39;, title: &#39;Symbol&#39;, dataKey: &#39;SYMBOL&#39; }, { key: &#39;PROFIT&#39;, title: &#39;Profit&#39;, dataKey: &#39;PROFIT&#39; }, ]&quot; :data=&quot;data&quot; :width=&quot;800&quot; :height=&quot;600&quot; :row-height=&quot;40&quot;/&gt;</li><li><strong>说明</strong>： <ul><li>el-table-v2 是 Element Plus 的虚拟滚动表格，适合 20,000+ 条数据。</li><li>动态调整 pageSize（当前为 9999），分批加载。</li></ul></li></ul><p><strong>3.5 错误处理</strong></p><ul><li><strong>实践</strong>： <ul><li>显示错误提示（如 Worker 报错或 API 失败）。</li><li>提供重试按钮。</li></ul></li><li><strong>Code</strong>： &lt;template&gt; &lt;div&gt; &lt;el-alert v-if=&quot;error&quot; type=&quot;error&quot; :title=&quot;error&quot; show-icon&gt; &lt;el-button @click=&quot;fetchData&quot;&gt;Retry&lt;/el-button&gt; &lt;/el-alert&gt; &lt;el-table v-else-if=&quot;!isLoading || data.length&quot; :data=&quot;data&quot;&gt; <em>&lt;!-- 表格内容 --&gt;</em> &lt;/el-table&gt; &lt;el-skeleton v-else /&gt; &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;const { data, isLoading, fetchData, error } = useOpenOrder(accountInfo);&lt;/script&gt;</li></ul><p><strong>3.6 实时更新提示</strong></p><ul><li><strong>实践</strong>： <ul><li>显示 totalFloatingPL 和 stats 的实时变化（如颜色闪烁）。</li><li>使用节流（已有 useThrottle）避免频繁更新。</li></ul></li><li><strong>Code</strong>： &lt;div&gt;总盈亏: &lt;span :class=&quot;{ &#39;text-green&#39;: throttledTotalPL &gt; 0 }&quot;&gt;{{ throttledTotalPL }}&lt;/span&gt;&lt;/div&gt;</li></ul></div>',1)])])}const c=e(r,[["render",s]]);export{q as __pageData,c as default};
